{
  "name": "The Duchess",
  "faction": "Crimson Court (Exiled)",
  "role": "Ally/Monster",
  "description": "A powerful monster exiled from the Crimson Court, seeking to reclaim her place as Queen. She fights alongside heroes as either a brilliant swordswoman or a ferocious beast.",
  "origin": {
    "background": "Born into a noble family obsessed with luxury and hidden knowledge.",
    "curse": "Afflicted by a vampiric crimson entity via forbidden rituals, gaining supernatural power and blood manipulation at the cost of monstrous transformation.",
    "downfall": "Rejected by her family and nobility due to her curse, cast into exile.",
    "goal": "Seeks redemption—or revenge—by aiding in the fight against monstrous horrors while battling her inner beast."
  },
  "forms": {
    "human": {
      "combatStyle": "Peerless fencer",
      "abilities": [
        "Precise thrusts",
        "Graceful parries",
        "Bleed-inflicting strikes"
      ]
    },
    "monster": {
      "combatStyle": "Ferocious beast",
      "abilities": [
        "Reckless charges",
        "Blood-fueled frenzy",
        "Savage mauls"
      ],
      "psychology": "Finds comfort in her beast form, possibly preferring it over her human self."
    }
  },
  "campingSkills": [
    "Demands luxury and comfort",
    "Replenishes Blood supplies using her affliction",
    "Provides tactical insight into Crimson Court strategies"
  ],
  "equipment": {
    "weapon": {
      "name": "Black Blade",
      "description": "An heirloom of noble craftsmanship, heavy and lethal."
    },
    "armor": {
      "name": "Tattered Dress",
      "description": "A padded, iron-plated relic of her former life, worn with elegance and deadly grace."
    }
  },
  "curse": {
    "name": "Crimson Curse",
    "description": "An otherworldly affliction granting strength and blood magic, at the cost of monstrous transformation and eternal thirst."
  },
  "physiology": {
    "species": "Industrial Fox",
    "traits": {
      "fur": "Bright yellow",
      "tail": "Visible through the cosset",
      "teeth": "Large and predatory",
      "chest": "Prominent"
    }
  }
}

data.scenario:
{
  "crimsonCurse": {
    "name": "The Crimson Curse",
    "type": "Supernatural Disease",
    "origin": {
      "source": "Experiments and rituals conducted by vampire-like Courtiers of the Crimson Court.",
      "event": "The estate's ancestor invited decadent aristocrats into his court, who later encountered The Blood God.",
      "transformation": "They received a so-called 'blessing' from the Blood God, which was in fact a horrific affliction."
    },
    "nature": {
      "description": "A contagious supernatural disease that twists its victims into ravenous, emaciated monsters.",
      "symptoms": [
        "Insatiable thirst for blood",
        "Physical and mental degeneration",
        "Loss of sanity when deprived of blood"
      ],
      "progression": [
        "Initial strength and vigor",
        "Growing dependency on The Blood",
        "Eventual madness and transformation"
      ]
    },
    "spread": {
      "vectors": [
        "Bodily fluids",
        "Ritual exposure",
        "Contact with infected"
      ],
      "affected": [
        "Nobles",
        "Mercenaries",
        "Servants",
        "Wild beasts"
      ],
      "consequence": "Entire regions fall into chaos as the curse spreads beyond the Crimson Court."
    },
    "loreImplication": "The Crimson Curse reflects the dangers of unchecked indulgence, forbidden power, and aristocratic decay."
  }
}
